#include <stdio.h>
#include <stdlib.h>

int main() {
    int size;
    printf("How many numbers? ");
    // scanf("%d", &size); // 사용자 입력 (예: 5)
    size = 5; 

    // 크기만큼 힙 할당
    int *arr = (int*)malloc(sizeof(int) * size);

    // 배열처럼 사용
    for(int i=0; i<size; i++) {
        arr[i] = i * 10;
        printf("%d ", arr[i]);
    }

    free(arr); // 전체 해제
    return 0;
}
